"""Glyph-template OCR for fixed pixel fonts."""
import base64
import json
from dataclasses import dataclass
from pathlib import Path

import numpy as np


def binarize(gray: np.ndarray, ink_max_gray: int) -> np.ndarray:
    return gray < ink_max_gray


def column_runs(ink: np.ndarray) -> list:
    cols = ink.any(axis=0).view(np.int8)
    edges = np.flatnonzero(np.diff(cols, prepend=0, append=0))
    return list(zip(edges[::2].tolist(), edges[1::2].tolist()))


def glyph_key(ink: np.ndarray) -> bytes:
    h, w = ink.shape
    assert h < 256 and w < 256
    return bytes((h, w)) + np.packbits(ink).tobytes()


@dataclass
class ReadResult:
    text: str
    unknown: int


class GlyphSet:
    def __init__(self, glyphs: dict, space_gap: int, tolerance: float = 0.06):
        self.space_gap = space_gap
        self.tolerance = tolerance
        self.exact = {}
        self.by_width = {}
        self._widths_desc = []
        for char, arrays in glyphs.items():
            for arr in arrays:
                self.add(char, arr)

    def add(self, char: str, ink: np.ndarray) -> None:
        ink = np.ascontiguousarray(ink, dtype=bool)
        if ink.ndim != 2 or ink.size == 0:
            raise ValueError("glyph template must be non-empty 2-D")
        key = glyph_key(ink)
        if self.exact.get(key) == char:
            return
        self.exact[key] = char
        w = ink.shape[1]
        self.by_width.setdefault(w, []).append((ink, char))
        self._widths_desc = sorted(self.by_width, reverse=True)

    def chars(self) -> set:
        """Characters that have at least one template (read-only copy)."""
        return {c for arrs in self.by_width.values() for _, c in arrs}

    def read(self, ink: np.ndarray) -> ReadResult:
        exact = self.exact
        widths = self._widths_desc
        out = []
        unknown = 0
        prev_x1 = None
        for x0, x1 in column_runs(ink):
            if prev_x1 is not None and x0 - prev_x1 >= self.space_gap:
                out.append(" ")
            prev_x1 = x1
            seg = ink[:, x0:x1]
            ch = exact.get(glyph_key(seg))
            if ch is not None:
                out.append(ch)
                continue
            seg_w = x1 - x0
            pos = 0
            while pos < seg_w:
                for w in widths:
                    if w > seg_w - pos:
                        continue
                    ch = exact.get(glyph_key(seg[:, pos:pos + w]))
                    if ch is not None:
                        out.append(ch)
                        pos += w
                        break
                else:
                    rest = seg[:, pos:]
                    ch = self._nearest(rest)
                    if ch is not None:
                        out.append(ch)
                    else:
                        out.append("?")
                        unknown += 1
                    pos = seg_w
                while pos < seg_w and not seg[:, pos].any():
                    pos += 1
        return ReadResult("".join(out), unknown)

    def _nearest(self, rest: np.ndarray):
        cands = self.by_width.get(rest.shape[1])
        if not cands:
            return None
        best_char = None
        best = None
        for arr, char in cands:
            if arr.shape != rest.shape:
                continue
            d = int(np.count_nonzero(arr != rest))
            if best is None or d < best:
                best, best_char = d, char
        if best is not None and best / rest.size <= self.tolerance:
            return best_char
        return None

    def save(self, path: Path) -> None:
        glyphs = []
        for items in self.by_width.values():
            for arr, char in items:
                h, w = arr.shape
                glyphs.append({
                    "char": char, "h": h, "w": w,
                    "bits": base64.b64encode(np.packbits(arr).tobytes()).decode("ascii"),
                })
        data = {"space_gap": self.space_gap, "tolerance": self.tolerance, "glyphs": glyphs}
        Path(path).write_text(json.dumps(data), encoding="utf-8")

    @classmethod
    def load(cls, path: Path) -> "GlyphSet":
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        gs = cls({}, data["space_gap"], data["tolerance"])
        for g in data["glyphs"]:
            h, w = g["h"], g["w"]
            bits = np.frombuffer(base64.b64decode(g["bits"]), np.uint8)
            arr = np.unpackbits(bits)[: h * w].reshape(h, w).astype(bool)
            gs.add(g["char"], arr)
        return gs

"""Slice shop rows into ink bitmaps and turn OCR text into Listings."""
import re
from dataclasses import dataclass

import numpy as np

from maplestory_classic_tool.catalog import fold_il
from maplestory_classic_tool.glyphs import binarize
from maplestory_classic_tool.layout import Layout
from maplestory_classic_tool.model import Listing

_NUM = r"[1-9]\d{0,2}(?:,\d{3})*"  # no leading zero
PRICE_RE = re.compile(rf"^({_NUM}) for ({_NUM}) mesos$")  # matches layout.price_format


def collapse_digit_spaces(text: str) -> str:
    """Drop a space between two digits/commas (tabular digits: the gap after "1" reads as one)."""
    return re.sub(r"(?<=[\d,]) (?=[\d,])", "", text)


def agrees_with_glyphs(glyph_text: str, ocr_text: str, unknown_chars: str) -> bool:
    """True only if OCR text fills in the glyph read without contradicting any known position.

    unknown_chars: the digit/comma characters the glyph set cannot read as a single glyph; only
    these can hide behind a "?" in the qty and price words.

    1. Digit gaps are collapsed on both sides (on the glyph side "?" counts as digit-like, so
       "1 ?,000" -> "1?,000"); whitespace runs become single spaces.
    2. A trailing fringe of "?" and spaces is trimmed from the glyph side.
    3. The trimmed glyph text must end with the known word "mesos" and contain the known word
       "for"; otherwise the read is too uncertain to trust.
    4. Both sides are split into words; the word counts must be equal.
    5. Each glyph word becomes a pattern; the OCR word must fullmatch it. In the qty word
       (first) and the price word (before "mesos"), a run of k "?" matches exactly k characters,
       each one of unknown_chars (no unknown_chars: any "?" there fails). Elsewhere a "?" run
       matches any non-empty non-space run.
    6. The qty word must start with a known digit, and the qty and price words must each contain
       a known digit: a price with no positional evidence stays unknown.
    """
    g = re.sub(r"(?<=[\d,?]) (?=[\d,?])", "", glyph_text)
    g = re.sub(r"\s+", " ", g).strip().rstrip("? ")
    o = re.sub(r"\s+", " ", collapse_digit_spaces(ocr_text)).strip()
    gw, ow = g.split(" "), o.split(" ")
    if len(gw) < 3 or gw[-1] != "mesos" or "for" not in gw:
        return False
    if len(gw) != len(ow):
        return False
    numeric = {0, len(gw) - 2}
    if not gw[0][:1].isdigit():
        return False
    for idx in numeric:
        if not re.search(r"[0-9]", gw[idx]):
            return False
    alphabet = "[" + re.escape("".join(unknown_chars)) + "]" if unknown_chars else None
    for idx, (gword, oword) in enumerate(zip(gw, ow)):
        if idx in numeric:
            if alphabet is None:
                if "?" in gword:
                    return False
                pattern = re.escape(gword)
            else:
                pattern = "".join(
                    f"{alphabet}{{{len(t)}}}" if t[0] == "?" else re.escape(t)
                    for t in re.findall(r"\?+|[^?]+", gword))
        else:
            pattern = r"\S+".join(re.escape(part) for part in re.split(r"\?+", gword))
        if re.fullmatch(pattern, oword) is None:
            return False
    return True


_THIN = "l.,':;i"  # glyphs a stroke fragment of an untemplated letter tends to match (N -> "l?", L -> "l...")
_CLUSTER_RE = re.compile(rf"[{re.escape(_THIN)}]*\?(?:[{re.escape(_THIN)}]*\?)*[{re.escape(_THIN)}]*")
MIN_NAME_EVIDENCE = 3  # known characters outside unknown clusters needed to trust an OCR name


def _name_norm(text: str) -> str:
    return re.sub(r"\s+", "", fold_il(text.replace("…", "...")).casefold())


def name_agrees(glyph_text: str, ocr_text: str) -> bool:
    """True if the OCR name agrees with the glyph name read at every known character.

    Both sides: I folded to l, casefolded, spaces removed. Each run of "?" in the glyph text
    (an untemplated glyph, possibly a touching cluster) matches 1-3 characters per "?"; thin glyphs
    touching such a run ("l", ".", ...) are absorbed into it, because a fragment of an untemplated
    letter often matches one (real reads: "INT" -> "ll?T", "LUK" -> "l.....?l?"). Everything else
    must match literally, and at least MIN_NAME_EVIDENCE known characters must remain.
    """
    g, o = _name_norm(glyph_text), _name_norm(ocr_text)
    if not g or not o:
        return False
    parts, literal, pos = [], 0, 0
    for m in _CLUSTER_RE.finditer(g):
        parts.append(re.escape(g[pos:m.start()]))
        literal += m.start() - pos
        c = m.group()
        q = c.count("?")
        parts.append(f".{{1,{3 * q + len(c) - q}}}")
        pos = m.end()
    parts.append(re.escape(g[pos:]))
    literal += len(g) - pos
    if literal < MIN_NAME_EVIDENCE:
        return False
    return re.fullmatch("".join(parts), o) is not None


@dataclass
class RowInk:
    row: int
    name: np.ndarray  # bool
    price: np.ndarray  # bool


def _box(gray: np.ndarray, origin: tuple, box: tuple, ink_max_gray: int):
    ox, oy = origin
    x, y, w, h = box
    x0, y0 = ox + x, oy + y
    if x0 < 0 or y0 < 0 or x0 + w > gray.shape[1] or y0 + h > gray.shape[0]:
        return None
    return binarize(gray[y0:y0 + h, x0:x0 + w], ink_max_gray)


def row_inks(gray: np.ndarray, anchor_xy: tuple, layout: Layout) -> list:
    """RowInk per row that has ink and lies fully inside the frame."""
    out = []
    for r in range(layout.rows):
        origin = layout.row_origin(anchor_xy, r)
        name = _box(gray, origin, layout.name_box, layout.ink_max_gray)
        price = _box(gray, origin, layout.price_box, layout.ink_max_gray)
        if name is None or price is None or not (name.any() or price.any()):
            continue
        out.append(RowInk(r, name, price))
    return out


def parse_price(text: str) -> tuple:
    """(qty, price) from "N for P mesos"; (None, None) on no match or an unknown glyph."""
    if "?" in text:
        return None, None
    m = PRICE_RE.match(collapse_digit_spaces(text))
    if not m:
        return None, None
    try:
        return int(m.group(1).replace(",", "")), int(m.group(2).replace(",", ""))
    except ValueError:
        return None, None


def to_listing(row: int, name_text: str, price_text: str, price_unknown: int,
               name_unknown: bool = False, price_filled: bool = False) -> Listing:
    """price_unknown: unknown-glyph count of the price box only (name '?' goes to fallback OCR).
    name_unknown / price_filled: the raw glyph reads had unknown glyphs (see Listing)."""
    qty, price = parse_price(price_text)
    uncertain = price_unknown > 0 or qty is None or price is None or not name_text.strip()
    return Listing(row, name_text, qty, price, uncertain, name_unknown, price_filled)

import statistics
import time

import numpy as np
import pytest

from maplestory_classic_tool.glyphs import GlyphSet, ReadResult, binarize, column_runs, glyph_key

_SHAPES = {
    "a": ["111", "101", "111", "101", "101"],
    "b": ["110", "101", "110", "101", "110"],
    "c": ["111", "100", "100", "100", "111"],
    "d": ["110", "101", "101", "101", "110"],
    "e": ["111", "100", "111", "100", "111"],
    "X": ["111", "111", "111", "111", "111"],
}


def _glyph(ch):
    return np.array([[c == "1" for c in row] for row in _SHAPES[ch]], bool)


def render(chars, gap=1, space=4):
    cols = []
    pending = gap
    for ch in chars:
        if ch == " ":
            pending = space
            continue
        if cols:
            cols.extend([np.zeros(5, bool)] * pending)
        cols.extend(list(_glyph(ch).T))
        pending = gap
    return np.stack(cols, axis=1)


def make_set(chars, tolerance=0.06):
    return GlyphSet({c: [_glyph(c)] for c in chars}, space_gap=3, tolerance=tolerance)


def test_binarize_threshold():
    out = binarize(np.array([[0, 99, 100, 255]], np.uint8), 100)
    assert out.tolist() == [[True, True, False, False]]


def test_column_runs():
    ink = np.array([[1, 1, 0, 0, 1, 0, 1]], bool)
    assert column_runs(ink) == [(0, 2), (4, 5), (6, 7)]


def test_column_runs_empty():
    assert column_runs(np.zeros((3, 4), bool)) == []


def test_glyph_key_includes_shape():
    k = glyph_key(_glyph("a"))
    assert k[:2] == bytes([5, 3])
    assert k[2:] == np.packbits(_glyph("a")).tobytes()


def test_read_exact_word_with_space():
    assert make_set("abc").read(render("ab c")) == ReadResult("ab c", 0)


def test_read_touching_glyphs_split():
    assert make_set("abc").read(render("abc", gap=0)).text == "abc"


def test_read_hamming_tolerance_accepts_one_flipped_pixel():
    gs = make_set("abc", tolerance=0.07)
    line = render("abc")
    line[2, 1] = ~line[2, 1]  # middle column of 'a'
    assert gs.read(line) == ReadResult("abc", 0)


def test_read_unknown_glyph_marks_question():
    r = make_set("ab").read(render("aXb"))
    assert r.text == "a?b" and r.unknown == 1


def test_add_keeps_structures_consistent():
    gs = make_set("ab")
    gs.add("c", _glyph("c"))
    gs.add("c", _glyph("c"))  # duplicate is a no-op
    assert len(gs.by_width[3]) == 3
    assert gs.read(render("abc")).text == "abc"


def test_save_load_roundtrip(tmp_path):
    gs = make_set("abc")
    path = tmp_path / "glyphs.json"
    gs.save(path)
    loaded = GlyphSet.load(path)
    line = render("ab c")
    assert loaded.read(line) == gs.read(line) == ReadResult("ab c", 0)
    assert loaded.read(render("abc", gap=0)).text == "abc"
    assert loaded.space_gap == 3


@pytest.mark.perf
def test_read_speed_line_under_200us():
    gs = make_set("abcde")
    line = render("abcde abcde abcde abcde", gap=1)
    assert gs.read(line).text == "abcde abcde abcde abcde"
    times = []
    for _ in range(200):
        t = time.perf_counter()
        gs.read(line)
        times.append(time.perf_counter() - t)
    assert statistics.median(times) < 200e-6


def test_read_height_mismatch_is_unknown_not_misread():
    gs = make_set("abc")
    line = np.vstack([render("a"), np.zeros((1, 3), bool)])  # 6 rows vs 5-row templates
    assert gs.read(line) == ReadResult("?", 1)


def test_add_rejects_empty_glyph():
    with pytest.raises(ValueError):
        make_set("a").add("z", np.zeros((5, 0), bool))

import statistics
import time
from pathlib import Path

import cv2
import numpy as np
import pytest

from maplestory_classic_tool.calibrate import load_fixtures
from maplestory_classic_tool.catalog import fold_il
from maplestory_classic_tool.detect import ShopLocator
from maplestory_classic_tool.glyphs import GlyphSet
from maplestory_classic_tool.layout import load_layout
from maplestory_classic_tool.shop import PRICE_RE, parse_price, row_inks, to_listing

ROOT = Path(__file__).resolve().parents[1]
FIXTURES = ROOT / "tests" / "fixtures" / "shops"
ASSETS = ROOT / "maplestory_classic_tool" / "assets"


@pytest.fixture(scope="module")
def layout():
    return load_layout(ASSETS / "layout.json")


@pytest.fixture(scope="module")
def anchor():
    return cv2.imread(str(ASSETS / "anchor.png"), cv2.IMREAD_GRAYSCALE)


@pytest.fixture(scope="module")
def glyphs():
    return GlyphSet.load(ASSETS / "glyphs.json")


@pytest.fixture(scope="module")
def fixtures(layout):
    return load_fixtures(FIXTURES, layout)


@pytest.fixture(scope="module")
def shops(fixtures):
    return [f for f in fixtures if f.shop]


def test_locate_on_each_shop_fixture(shops, anchor, layout):
    loc = ShopLocator(anchor)
    assert len(shops) >= 7
    for f in shops:
        loc.reset()
        pos = loc.locate(f.gray)
        assert pos is not None, f.name
        h, w = anchor.shape
        assert 0 <= pos[0] <= f.gray.shape[1] - w and 0 <= pos[1] <= f.gray.shape[0] - h
        ox, oy = layout.row_origin(pos, layout.rows - 1)
        assert oy + layout.row_pitch <= f.gray.shape[0], f.name


def test_locate_negatives_none(fixtures, anchor):
    negs = [f for f in fixtures if not f.shop]
    assert {f.name for f in negs} == {"noshop_npc", "noshop_fm", "noshop_grind", "noshop_partialinv"}
    loc = ShopLocator(anchor)
    for f in negs:
        assert loc.locate(f.gray) is None, f.name


def test_negative_clears_cache(shops, fixtures, anchor):
    loc = ShopLocator(anchor)
    assert loc.locate(shops[0].gray) is not None
    neg = next(f for f in fixtures if not f.shop)
    assert loc.locate(neg.gray) is None
    assert loc._pos is None


def test_locate_cached_position_reused(shops, anchor):
    loc = ShopLocator(anchor)
    pos = loc.locate(shops[0].gray)
    assert loc._pos == pos
    assert loc.locate(shops[0].gray) == pos


def test_locate_after_window_moved(shops, anchor):
    # convention: np.roll(gray, (21, 37), axis=(0, 1)) moves content 21 rows down, 37 cols right
    gray = shops[0].gray
    loc = ShopLocator(anchor)
    x, y = loc.locate(gray)
    moved = np.roll(gray, (21, 37), axis=(0, 1))
    assert loc.locate(moved) == (x + 37, y + 21)


@pytest.mark.perf
def test_locate_uses_cache_fast(shops, anchor):
    gray = shops[0].gray
    loc = ShopLocator(anchor)
    assert loc.locate(gray) is not None
    times = []
    for _ in range(200):
        t = time.perf_counter()
        loc.locate(gray)
        times.append(time.perf_counter() - t)
    med = statistics.median(times) * 1000
    print(f"cached locate median {med:.4f} ms")
    assert med < 0.2
    full = []
    for _ in range(20):
        loc.reset()
        t = time.perf_counter()
        loc.locate(gray)
        full.append(time.perf_counter() - t)
    print(f"full search median {statistics.median(full) * 1000:.2f} ms")


def _expected(f):
    return {r: row for r, row in enumerate(f.rows) if isinstance(row, dict)}


def test_row_inks_skips_sold_and_empty(shops, anchor, layout):
    for f in shops:
        axy = ShopLocator(anchor).locate(f.gray)
        got = {ri.row for ri in row_inks(f.gray, axy, layout)}
        occluded = {r for r, row in enumerate(f.rows) if row == "occluded"}
        assert got - occluded == set(_expected(f)), f.name
        for ri in row_inks(f.gray, axy, layout):
            assert ri.name.dtype == bool and ri.price.dtype == bool


def test_row_inks_skips_rows_outside_frame(layout):
    gray = np.zeros((100, 100), np.uint8)
    assert row_inks(gray, (50, 50), layout) == []


def test_parse_price():
    assert parse_price("100 for 5,000 mesos") == (100, 5000)
    assert parse_price("1 for 2,147,483,647 mesos") == (1, 2147483647)
    assert PRICE_RE.match("1 for 3,000 mesos")


def test_parse_price_collapses_digit_gap():
    assert parse_price("1 for 1 2,000 mesos") == (1, 12000)


def test_parse_price_unknown_glyph():
    assert parse_price("1 for 5,?00 mesos") == (None, None)
    assert parse_price("garbage") == (None, None)


def test_to_listing():
    ok = to_listing(2, "Maple Staff", "3 for 4,500 mesos", 0)
    assert (ok.row, ok.name, ok.qty, ok.price, ok.uncertain) == (2, "Maple Staff", 3, 4500, False)
    assert to_listing(0, "X", "3 for 4,500 mesos", 1).uncertain
    assert to_listing(0, "X", "?", 0).uncertain
    assert to_listing(0, "  ", "3 for 4,500 mesos", 0).uncertain
    assert not to_listing(0, "Na?me", "3 for 4,500 mesos", 0).uncertain


def test_rows_read_match_labels(shops, anchor, layout, glyphs):
    checked = 0
    for f in shops:
        axy = ShopLocator(anchor).locate(f.gray)
        exp = _expected(f)
        got = {}
        for ri in row_inks(f.gray, axy, layout):
            if f.rows[ri.row] == "occluded":
                continue
            n, p = glyphs.read(ri.name), glyphs.read(ri.price)
            got[ri.row] = to_listing(ri.row, n.text, p.text, p.unknown)
        assert set(got) == set(exp), f.name
        for r, row in exp.items():
            lst = got[r]
            assert not lst.uncertain, (f.name, r, lst)
            assert (lst.qty, lst.price) == (row["qty"], row["price"]), (f.name, r)
            if "?" in lst.name and set(fold_il(row["name"])) - set(glyphs.chars()) - {" "}:
                continue  # e.g. "LUK": no U/K templates; the OCR fallback reads these names
            assert fold_il(lst.name) == fold_il(row["name"]), (f.name, r)
            checked += 1
    assert checked > 20


def test_parse_price_rejects_malformed_grouping():
    for bad in ("1 for ,899 mesos", "1 for 8,00 mesos", "1 for 1,,899 mesos",
                "1,0 for 5 mesos", "1 for 1234,567 mesos"):
        assert parse_price(bad) == (None, None), bad


def test_parse_price_accepts_well_formed():
    assert parse_price("1 for 3,000 mesos") == (1, 3000)
    assert parse_price("100 for 5,000 mesos") == (100, 5000)
    assert parse_price("1 for 2,147,483,647 mesos") == (1, 2147483647)
    assert parse_price("1 for 99 mesos") == (1, 99)


REJECT_PAIRS = [
    ("1 for 1?? ?????", "1 for 1 mesos"),
    ("1 for 4?? ?????", "1 for 4 mesos"),
    ("1 for ?", "1 for 5 mesos"),
    ("1 for ??", "1 for 5 mesos"),
    ("?", "1 for 5 mesos"),
    ("??", "1 for 5 mesos"),
    ("1 for 1?,000 mesos", "1 for 1,000 mesos"),
    ("1 for ?? mesos", "1 for 88 mesos"),        # no known price digit
    ("? for 1,000 mesos", "1 for 1,000 mesos"),  # no known qty digit
    ("1 for 1?? ?????", "1 for 100 mesos"),      # glyph lacks known "mesos"
    ("1 for ??,000 mesos", "1 for 8,000 mesos"),   # exact length: true 88,000
    ("1 for 5?? mesos", "1 for 58 mesos"),
    ("1 for ?,500 mesos", "1 for 0,500 mesos"),    # 0 is a known glyph, cannot hide in ?
    ("1 for ?00 mesos", "1 for 000 mesos"),
    ("1 ? for 5,000 mesos", "180 for 5,000 mesos"),
    ("? 1 for 3,000 mesos", "11 for 3,000 mesos"),  # leading ? in qty
    ("1 for ?,000 mesos", "1 for 3,000 mesos"),     # 8 read as 3
]
ACCEPT_PAIRS = [
    ("1 for ?,000 mesos", "1 for 8,000 mesos"),
    ("1 for ??,000 mesos", "1 for 88,000 mesos"),
    ("1 for 12,000 mesos??", "1 for 12,000 mesos"),
    ("1 for 1 ?,000 mesos", "1 for 18,000 mesos"),  # digit-gap collapse with ?
    ("10? for 5,000 mesos", "108 for 5,000 mesos"),
]


@pytest.mark.parametrize("glyph,ocr", REJECT_PAIRS)
